use std::fs

fn walk(keys: Vec<int>, lefts: Vec<int>, rights: Vec<int>, n: int, out: Vec<string>) -> Vec<string> {
    let mut res = out
    if n < 0 {
        return res
    }
    res = walk(keys, lefts, rights, lefts[n], res)
    res.push("${keys[n]}")
    walk(keys, lefts, rights, rights[n], res)
}

fn height(lefts: Vec<int>, rights: Vec<int>, n: int) -> int {
    if n < 0 {
        return 0
    }
    let a = height(lefts, rights, lefts[n])
    let b = height(lefts, rights, rights[n])
    if a > b { a + 1 } else { b + 1 }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut keys: Vec<int> = []
    let mut lefts: Vec<int> = []
    let mut rights: Vec<int> = []
    let mut root: int = -1
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        let mut x: int = 0
        if parts.len() > 1 {
            x = parts[1].parse::<int>().unwrap_or(0)
        }
        if cmd == "insert" {
            let mut cur: int = root
            let mut parent: int = -1
            let mut went_left = false
            let mut found = false
            while cur >= 0 {
                if keys[cur] == x {
                    found = true
                    break
                }
                parent = cur
                if x < keys[cur] {
                    went_left = true
                    cur = lefts[cur]
                } else {
                    went_left = false
                    cur = rights[cur]
                }
            }
            if found {
                println("dup")
            } else {
                let idx: int = keys.len() as int
                keys.push(x)
                lefts.push(-1)
                rights.push(-1)
                if parent < 0 {
                    root = idx
                } else if went_left {
                    lefts[parent] = idx
                } else {
                    rights[parent] = idx
                }
                println("ok")
            }
        } else if cmd == "contains" {
            let mut cur: int = root
            let mut found = false
            while cur >= 0 {
                if keys[cur] == x {
                    found = true
                    break
                }
                if x < keys[cur] { cur = lefts[cur] } else { cur = rights[cur] }
            }
            if found { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let mut cur: int = root
            let mut parent: int = -1
            let mut went_left = false
            let mut found = false
            while cur >= 0 {
                if keys[cur] == x {
                    found = true
                    break
                }
                parent = cur
                if x < keys[cur] {
                    went_left = true
                    cur = lefts[cur]
                } else {
                    went_left = false
                    cur = rights[cur]
                }
            }
            if !found {
                println("missing")
            } else {
                if lefts[cur] >= 0 && rights[cur] >= 0 {
                    let mut sp: int = cur
                    let mut s: int = rights[cur]
                    while lefts[s] >= 0 {
                        sp = s
                        s = lefts[s]
                    }
                    keys[cur] = keys[s]
                    let child: int = rights[s]
                    if sp == cur {
                        rights[sp] = child
                    } else {
                        lefts[sp] = child
                    }
                } else {
                    let mut child: int = lefts[cur]
                    if child < 0 {
                        child = rights[cur]
                    }
                    if parent < 0 {
                        root = child
                    } else if went_left {
                        lefts[parent] = child
                    } else {
                        rights[parent] = child
                    }
                }
                println("ok")
            }
        } else if cmd == "inorder" {
            if root < 0 {
                println("<empty>")
            } else {
                let out: Vec<string> = []
                let res = walk(keys, lefts, rights, root, out)
                println(res.join(" "))
            }
        } else if cmd == "height" {
            println("${height(lefts, rights, root)}")
        } else if cmd == "min" {
            if root < 0 {
                println("empty")
            } else {
                let mut c: int = root
                while lefts[c] >= 0 {
                    c = lefts[c]
                }
                println("${keys[c]}")
            }
        } else if cmd == "max" {
            if root < 0 {
                println("empty")
            } else {
                let mut c: int = root
                while rights[c] >= 0 {
                    c = rights[c]
                }
                println("${keys[c]}")
            }
        }
    }
}

